  示例: "7月交费客户（当前时间为2026年）" → {"field": "polNoInfo.paytodate", "operator": "RANGE", "value": {"min": "2026-07-01 00:00:00", "max": "2026-07-31 23:59:59"}}

  示例: "七月份缴费客户（当前时间为2026年）" → {"field": "polNoInfo.paytodate", "operator": "RANGE", "value": {"min": "2026-07-01 00:00:00", "max": "2026-07-31 23:59:59"}}

  示例: "要交保费的客户" → {"field": "polNoInfo.paytodate", "operator": "EXISTS", "value": ""}

  示例: "上个月刚缴完费的客户" → {"field": "polNoInfo.paytodate", "operator": "RANGE", "value": {"min": "2026-06-01 00:00:00", "max": "2026-06-30 23:59:59"}}

